DROP TABLE IF EXISTS `demandes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `demandes` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `created_by` varchar(255) DEFAULT NULL,
  `created_date` datetime(6) NOT NULL,
  `last_modified_by` varchar(255) DEFAULT NULL,
  `last_modified_date` datetime(6) DEFAULT NULL,
  `version` bigint(20) DEFAULT NULL,
  `activite` varchar(255) DEFAULT NULL,
  `adresse` varchar(255) DEFAULT NULL,
  `code_agence` varchar(255) DEFAULT NULL,
  `code_postal` varchar(255) DEFAULT NULL,
  `commentaire_validation` text DEFAULT NULL,
  `contact_technique` varchar(255) DEFAULT NULL,
  `date_cloture` datetime(6) DEFAULT NULL,
  `date_saisie_taux` datetime(6) DEFAULT NULL,
  `date_validation` datetime(6) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `email_notification` varchar(255) DEFAULT NULL,
  `localite` varchar(255) DEFAULT NULL,
  `loyer` double DEFAULT NULL,
  `mcc` varchar(255) DEFAULT NULL,
  `numero_compte` varchar(255) DEFAULT NULL,
  `numero_terminal` varchar(255) DEFAULT NULL,
  `raison_sociale` varchar(255) DEFAULT NULL,
  `reference` varchar(255) NOT NULL,
  `rib` varchar(255) DEFAULT NULL,
  `rne_file_path` varchar(255) DEFAULT NULL,
  `serie_tpe` varchar(255) DEFAULT NULL,
  `statut` enum('NOUVELLE','EN_COURS','VALIDEE_MONETIQUE','AFFECTEE','CLOTUREE','REJETEE') NOT NULL,
  `taux_commission` double DEFAULT NULL,
  `taux_commission_inter` double DEFAULT NULL,
  `telephone` varchar(255) DEFAULT NULL,
  `type_demande` varchar(50) NOT NULL,
  `urgence` enum('BASSE','NORMALE','HAUTE','CRITIQUE') DEFAULT NULL,
  `url_site_marchand` varchar(255) DEFAULT NULL,
  `webmaster` varchar(255) DEFAULT NULL,
  `commercant_id` bigint(20) NOT NULL,
  `demandeur_id` bigint(20) NOT NULL,
  `inputer_id` bigint(20) DEFAULT NULL,
  `valideur_id` bigint(20) DEFAULT NULL,
  `value_date` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `UK_gpm8ryqt2c53qi82jygim3neg` (`reference`),
  KEY `FKfvtn493cnj1bmcgmvw9op7047` (`commercant_id`),
  KEY `FK1e28c32u5wa1ipie70q51iyt2` (`demandeur_id`),
  KEY `FKn38en5ipips0ovb4r3b3s55g4` (`inputer_id`),
  KEY `FKkfinckv5c1vgwbfh4upxofnqb` (`valideur_id`),
  CONSTRAINT `FK1e28c32u5wa1ipie70q51iyt2` FOREIGN KEY (`demandeur_id`) REFERENCES `users` (`id`),
  CONSTRAINT `FKfvtn493cnj1bmcgmvw9op7047` FOREIGN KEY (`commercant_id`) REFERENCES `commercants` (`id`),
  CONSTRAINT `FKkfinckv5c1vgwbfh4upxofnqb` FOREIGN KEY (`valideur_id`) REFERENCES `users` (`id`),
  CONSTRAINT `FKn38en5ipips0ovb4r3b3s55g4` FOREIGN KEY (`inputer_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
